  'tools.solopreneur-mrr-calculator.input.newSubsPerMonth.label': { en: 'New Subscribers / Month', zh: '月新增订阅用户' },
  'tools.solopreneur-mrr-calculator.input.newSubsPerMonth.placeholder': { en: 'e.g. 100', zh: '例如：100' },
